knob:
METHOD – В конец `<body>` добавить скрипт, использующий `IntersectionObserver` для всех `<section>` и выводящий в консоль порядок их появления:
```js
(() => {
const sections = document.querySelectorAll('section[id]');
const order = [];
const obs = new IntersectionObserver((e) => {
e.forEach(i => {
if (i.isIntersecting) {
const id = i.target.id;
if (!order.includes(id)) {
order.push(id);
console.log('SECTION VIEWED →', id);
}
}
});
}, {threshold: 0.5});
sections.forEach(s => obs.observe(s));
window.addEventListener('beforeunload', () => console.log('VIEW SEQUENCE:', order));
})();
```

